import{_ as i,a0 as a,w as p,s as r,ao as m,I as l,a1 as e,A as s,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"交友網站的2000萬用户數據遭泄露 | LCTT x X-CMD","titleTemplate":false,"description":"交友網站的2000萬用户數據遭泄露 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"交友網站的2000萬用户數據遭泄露 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"交友網站的2000萬用户數據遭泄露 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20150126 Data of 20 Million Users Stolen from Dating Website","title":"交友網站的2000萬用户數據遭泄露","tag":"201501","desc":""},"relativePath":"201501/20150126 Data of 20 Million Users Stolen from Dating Website.md","filePath":"[post].md"}'),f={name:"201501/20150126 Data of 20 Million Users Stolen from Dating Website.md"};function u(d,t,T,g,D,C){const n=a("Link");return p(),r("div",null,[t[15]||(t[15]=m('<h1 id="交友網站的2000萬用户數據遭泄露" tabindex="-1">交友網站的2000萬用户數據遭泄露 <a class="header-anchor" href="#交友網站的2000萬用户數據遭泄露" aria-label="Permalink to “交友網站的2000萬用户數據遭泄露”">​</a></h1><p><em>泄露數據包括Gmail、Hotmail以及Yahoo郵箱</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Data-of-20-Million-Users-Stolen-from-Dating-Website-471179-2.jpg" alt="泄露的數據很可能來自於在線交友網站Topface"></p><p>#一名黑客非法竊取了在線交友網站Topface一個包含2000萬用户資料的資料庫。</p><p>目前並不清楚這些數據是否已經公開，但是根據某些未公開頁面的消息説，某個網名為“Mastermind”的人聲稱掌握着這些數據。</p><p>#泄露數據列表涵蓋了全世界數百個域名</p><p>此人號稱泄露數據的內容100%真實有效，而Easy Solutions的CTO，Daniel Ingevaldson 週日在一篇Blog中説道，泄露數據包括Hotmail、Yahoo和Gmail等郵箱地址。</p><p>Easy Solutions是一家位於美國的公司，提供多個不同平台的網絡檢測與安全防護產品。</p><p>據Ingevaldson所説，泄露的數據中，700萬來自於Hotmail，250萬來自於Yahoo，220萬來自於Gmail.com。</p><p>我們並不清楚這些數據是可以直接登錄郵箱賬户的用户名和密碼，還是登錄交友網站的賬户。另外，也不清楚這些數據在資料庫中是加密狀態還是明文存在的。</p><p>郵箱地址常常被用於在線網站的登錄用户名，用户可以憑藉唯一密碼進行登錄。然而重複使用同一個密碼是許多用户的常用作法，同一個密碼可以登錄許多在線賬户。</p>',11)),l("p",null,[e(n,{href:"1"},{default:s(()=>[...t[0]||(t[0]=[o("Ingevaldson 還説",-1)])]),_:1}),t[1]||(t[1]=o("：“看起來，這些數據事實上涵蓋了全世界數百個域名。除了原始被黑的網頁，黑客和不法分子很可能利用竊取的帳密進行暴庫、自動掃描、危害包括銀行業、旅遊業以及email提供商在內的多個網站。”",-1))]),t[16]||(t[16]=l("p",null,"#預計將披露更多信息",-1)),t[17]||(t[17]=l("p",null,"據我們的多個消息源爆料，數據的泄露源就是Topface，一個包含9000萬用户的在線交友網站。其總部位於俄羅斯聖彼得堡，超過50%的用户來自於俄羅斯以外的國家。",-1)),t[18]||(t[18]=l("p",null,"我們聯繫了Topface，向他們求證最近是否遭受了可能導致如此大量數據泄露的網絡攻擊；但目前我們仍未收到該公司的回覆。",-1)),t[19]||(t[19]=l("p",null,"攻擊者可能無需獲得非法訪問權限就竊取了這些數據，Easy Solutions 推測攻擊者很可能針對網站客户端使用釣魚郵件直接獲取到了用户數據。",-1)),t[20]||(t[20]=l("p",null,"我們無法通過Easy Solutions的在線網站聯繫到他們，但我們已經嘗試了其他交互通訊方式，目前正在等待更多信息的披露。",-1)),t[21]||(t[21]=l("hr",null,null,-1)),l("p",null,[t[3]||(t[3]=o("via:",-1)),e(n,{href:"http://news.softpedia.com/news/Data-of-20-Million-Users-Stolen-from-Dating-Website-471179.shtml"},{default:s(()=>[...t[2]||(t[2]=[o("http://news.softpedia.com/news/Data-of-20-Million-Users-Stolen-from-Dating-Website-471179.shtml",-1)])]),_:1})]),t[22]||(t[22]=l("p",null,"本文發佈時間:26 Jan 2015, 10:20 GMT",-1)),l("p",null,[t[5]||(t[5]=o("作者：",-1)),e(n,{href:"http://news.softpedia.com/editors/browse/ionut-ilascu"},{default:s(()=>[...t[4]||(t[4]=[o("Ionut Ilascu",-1)])]),_:1})]),l("p",null,[t[7]||(t[7]=o("譯者：",-1)),e(n,{href:"https://github.com/tinyeyeser"},{default:s(()=>[...t[6]||(t[6]=[o("Mr小眼兒",-1)])]),_:1})]),l("p",null,[t[9]||(t[9]=o("校對：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[8]||(t[8]=[o("Caroline",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[o("Linux中國",-1)])]),_:1}),t[14]||(t[14]=o(" 榮譽推出",-1))])])}const x=i(f,[["render",u]]);export{b as __pageData,x as default};
